import { resolveStarterPackage } from './starter-package-service.js';
import { createConversationStore } from './conversation-store.js';
import { createReviewSessionStore } from './review-session-store.js';
import { createTaskStore } from './task-store.js';
import { createReviewVersionStore } from './review-version-store.js';
import { createDiscoveryStore } from './discovery-store.js';
import { createStrategyStore, strategyFields } from './strategy-store.js';
import { createStrategyPacketStore } from './strategy-packet-store.js';

for (const href of ['/studio4/responsive.css','/studio4/history.css','/studio4/library.css','/studio4/comments.css','/studio4/review-sessions.css','/studio4/tasks.css','/studio4/review-versions.css','/studio4/discovery.css','/studio4/strategy.css','/studio4/strategy-packet.css']) document.head.append(Object.assign(document.createElement('link'), { rel: 'stylesheet', href }));
const store = createStudioStore(seedState), registry = createComponentRegistry(), $ = selector => document.querySelector(selector), canvas = $('#page-canvas');
const conversationStore = createConversationStore(store); let commentsOpen = false;
const reviewVersionStore = createReviewVersionStore(store);
const reviewSessionStore = createReviewSessionStore(store, conversationStore, reviewVersionStore);
const taskStore = createTaskStore(store, conversationStore); let tasksOpen = false;
const discoveryStore = createDiscoveryStore(store);
const strategyStore = createStrategyStore(store,discoveryStore);
const packetStore=createStrategyPacketStore(store,discoveryStore,strategyStore);
componentDefinitions.forEach(definition => registry.register(definition));
const pageTemplateLibrary = createLibraryRegistry(); librarySeeds.forEach(item => pageTemplateLibrary.register(item));
let insertionIndex = 0;
const read = (object, path) => path.split('.').reduce((value, key) => value?.[key], object);

const deviceBar = document.createElement('nav');
deviceBar.className = 'device-switch';
deviceBar.innerHTML = '<button data-device="desktop">Desktop</button><button data-device="tablet">Tablet</button><button data-device="mobile">Mobile</button>';
document.querySelector('.mode-switch').before(deviceBar);
import('./library-ui.js').then(({ initLibraryUI }) => initLibraryUI({ store, registry }));

document.querySelectorAll('[data-setting]').forEach(control => control.addEventListener('change', () => {
  const value = control.type === 'range' ? Number(control.value) : control.value;
  store.updateDesignSettings({ [control.dataset.setting]: value });
  const output = control.parentElement.querySelector('output'); if (output) output.value = value;
}));

const historyDock = document.createElement('aside');
historyDock.className = 'history-dock';
historyDock.innerHTML = '<header><strong>Workspace History</strong><button data-close-history>×</button></header><div class="history-actions"><button data-undo>Undo</button><button data-redo>Redo</button></div><ol data-history-list></ol>';
document.body.append(historyDock);
const historyToggle = document.createElement('button'); historyToggle.className = 'history-toggle'; historyToggle.textContent = 'History'; document.querySelector('.mode-switch').after(historyToggle);
const websiteToggle = document.createElement('button'); websiteToggle.className = 'website-toggle'; websiteToggle.textContent = 'Start Website'; historyToggle.after(websiteToggle); websiteToggle.onclick = openWebsiteDialog;
const commentsToggle = document.createElement('button'); commentsToggle.className = 'comments-toggle'; commentsToggle.textContent = 'Comments'; websiteToggle.after(commentsToggle);
const tasksToggle = document.createElement('button'); tasksToggle.className = 'tasks-toggle'; tasksToggle.textContent = 'Tasks'; commentsToggle.after(tasksToggle);
const versionsToggle = document.createElement('button'); versionsToggle.className = 'versions-toggle'; versionsToggle.textContent = 'Versions'; tasksToggle.after(versionsToggle);
const discoveryToggle = document.createElement('button'); discoveryToggle.className = 'discovery-toggle'; discoveryToggle.textContent = 'Discovery'; versionsToggle.after(discoveryToggle);
const strategyToggle=document.createElement('button');strategyToggle.className='strategy-toggle';strategyToggle.textContent='Strategy';discoveryToggle.after(strategyToggle);
const packetToggle=document.createElement('button');packetToggle.className='packet-toggle';packetToggle.textContent='Strategy Packet';strategyToggle.after(packetToggle);
historyToggle.onclick = () => historyDock.classList.toggle('open'); historyDock.querySelector('[data-close-history]').onclick = () => historyDock.classList.remove('open'); historyDock.querySelector('[data-undo]').onclick = () => store.undo(); historyDock.querySelector('[data-redo]').onclick = () => store.redo();

function renderHistory() {
  const history = store.getHistory(), list = historyDock.querySelector('[data-history-list]');
  historyDock.querySelector('[data-undo]').disabled = !history.canUndo; historyDock.querySelector('[data-redo]').disabled = !history.canRedo;
  list.replaceChildren(...history.entries.map((entry, index) => { const item = document.createElement('li'), button = document.createElement('button'); item.classList.toggle('current', index === history.cursor); button.innerHTML = `<strong>${entry.label}</strong><small>${new Date(entry.timestamp).toLocaleTimeString()} · ${entry.affectedObject}</small>`; button.onclick = () => store.restoreTo(entry.id); item.append(button); return item; }).reverse());
}
store.subscribe(renderHistory); renderHistory();

const versionsDock = document.createElement('aside'); versionsDock.className = 'versions-dock'; versionsDock.innerHTML = '<header><div><small>Formal checkpoints</small><strong>Version History</strong></div><button data-close-versions>×</button></header><button data-create-version>＋ Create Version</button><ol data-version-list></ol><section data-version-detail></section>'; document.body.append(versionsDock);
versionsToggle.onclick = () => versionsDock.classList.toggle('open'); versionsDock.querySelector('[data-close-versions]').onclick = () => versionsDock.classList.remove('open');
versionsDock.querySelector('[data-create-version]').onclick = () => { const label = `Website version ${reviewVersionStore.list().length + 1}`; reviewVersionStore.create({ label }); };
function inspectVersion(item) { const snapshot = reviewVersionStore.inspect(item.id), overlay = document.createElement('div'); overlay.className = 'version-inspection'; const pages = snapshot.website.pageIds.map(id => snapshot.pages[id]); overlay.innerHTML = `<header><div><small>Read-only review version</small><strong>${item.label}</strong></div><button>Exit inspection</button></header><main><h1>${snapshot.website.name}</h1>${pages.map(page => `<article><h2>${page.name}</h2><small>${page.slug} · ${page.componentInstanceIds.length} components</small>${page.componentInstanceIds.map(id => { const component = snapshot.componentInstances[id]; return `<section><strong>${component.definitionType}</strong><span>${component.content.heading || component.content.eyebrow || component.variantId}</span></section>`; }).join('')}</article>`).join('')}</main>`; overlay.querySelector('button').onclick = () => { reviewVersionStore.exitInspection(); overlay.remove(); }; document.body.append(overlay); }
function confirmVersionRestore(item) { const overlay = document.createElement('div'); overlay.className = 'page-dialog'; overlay.innerHTML = `<form><h2>Restore “${item.label}”?</h2><p>This replaces the current Website as one undoable Workspace transaction. Review records remain unchanged.</p><div><button type="button">Cancel</button><button type="submit">Restore this version</button></div></form>`; overlay.querySelector('[type="button"]').onclick = () => overlay.remove(); overlay.querySelector('form').onsubmit = event => { event.preventDefault(); reviewVersionStore.restore(item.id, true); overlay.remove(); }; document.body.append(overlay); }
function renderVersions() { const state = reviewVersionStore.getState(), versions = reviewVersionStore.list(), list = versionsDock.querySelector('[data-version-list]'); list.replaceChildren(...versions.map(item => { const row = document.createElement('li'), button = document.createElement('button'); row.classList.toggle('selected', item.id === state.selectedId); button.innerHTML = `<strong>${item.label}</strong><small>${item.source} · ${item.pageCount} pages · ${item.componentCount} components${item.isCurrent ? ' · current' : ''}</small><small>${new Date(item.createdAt).toLocaleString()} · ${item.createdBy.name}</small>`; button.onclick = () => reviewVersionStore.select(item.id); row.append(button); return row; }).reverse()); const detail = versionsDock.querySelector('[data-version-detail]'); detail.replaceChildren(); if (!state.selectedId) return; const item = reviewVersionStore.get(state.selectedId), session = item.reviewSessionId ? reviewSessionStore.getState().sessions[item.reviewSessionId] : null, approvals = session?.approvalRecords.filter(record => record.reviewVersionId === item.id).length || 0; detail.innerHTML = `<label>Version label<input value="${item.label.replaceAll('&','&amp;').replaceAll('"','&quot;')}"></label><small>${item.documentFingerprint}</small><small>${session ? `Review: ${session.title}` : 'Manual checkpoint'} · ${approvals} approval record${approvals === 1 ? '' : 's'}</small><div><button data-inspect>Inspect</button><button data-restore>Restore this version</button></div>`; detail.querySelector('input').onchange = event => reviewVersionStore.rename(item.id,event.target.value); detail.querySelector('[data-inspect]').onclick = () => inspectVersion(item); detail.querySelector('[data-restore]').onclick = () => confirmVersionRestore(item); }
reviewVersionStore.subscribe(renderVersions); store.subscribe(renderVersions); reviewSessionStore?.subscribe?.(renderVersions); renderVersions();

const discoveryDock=document.createElement('aside');discoveryDock.className='discovery-dock';discoveryDock.innerHTML='<header><div><small>Strategy input</small><strong>Website Discovery</strong></div><button data-close-discovery>×</button></header><div data-discovery-summary></div><nav data-discovery-sections></nav><section data-discovery-questions></section><section data-discovery-inputs></section>';document.body.append(discoveryDock);
discoveryToggle.onclick=()=>{discoveryStore.ensureCurrent();discoveryDock.classList.toggle('open');};discoveryDock.querySelector('[data-close-discovery]').onclick=()=>discoveryDock.classList.remove('open');
function renderDiscovery(){const state=discoveryStore.getState();if(!state.selectedId)return;const item=discoveryStore.get(state.selectedId),definition=discoveryStore.definition,summary=discoveryDock.querySelector('[data-discovery-summary]');summary.innerHTML=`<strong>${item.progress.state.replaceAll('-',' ')}</strong><small>${item.progress.requiredAnswered}/${item.progress.requiredTotal} required · ${item.progress.answered}/${item.progress.total} overall${item.contextAvailable?'':' · original Website unavailable'}</small>`;const sectionNav=discoveryDock.querySelector('[data-discovery-sections]');sectionNav.replaceChildren(...definition.sections.map(section=>{const progress=item.progress.sections.find(value=>value.id===section.id),button=document.createElement('button');button.classList.toggle('selected',section.id===state.selectedSectionId);button.innerHTML=`${section.title}<small>${progress.requiredAnswered}/${progress.requiredTotal} required</small>`;button.onclick=()=>discoveryStore.selectSection(section.id);return button;}));const section=definition.sections.find(value=>value.id===state.selectedSectionId),questions=discoveryDock.querySelector('[data-discovery-questions]');questions.innerHTML=`<h3>${section.title}</h3>`;for(const questionId of section.questionIds){const question=definition.questions.find(value=>value.id===questionId),response=item.responses[question.id],field=document.createElement('fieldset');field.innerHTML=`<legend>${question.label}${question.required?' *':''}</legend>${question.helperText?`<small>${question.helperText}</small>`:''}`;if(question.type==='multi-choice'){for(const choice of question.choices){const label=document.createElement('label'),control=document.createElement('input');control.type='checkbox';control.checked=(response?.answer||[]).includes(choice);control.onchange=()=>{const values=[...field.querySelectorAll('input:checked')].map(input=>input.value);discoveryStore.respond(item.id,question.id,values,'client');};control.value=choice;label.append(control,choice.replaceAll('-',' '));field.append(label);}}else{let control;if(question.type==='long-text'){control=document.createElement('textarea');control.value=response?.answer||'';}else if(question.type==='short-text'){control=document.createElement('input');control.value=response?.answer||'';}else{control=document.createElement('select');control.append(new Option('Choose…',''),...question.choices.map(choice=>new Option(choice.replaceAll('-',' '),choice)));control.value=response?.answer||'';}control.onchange=()=>discoveryStore.respond(item.id,question.id,control.value,'client');field.append(control);}questions.append(field);}const inputs=discoveryStore.getRecommendationInputs(item.id),preview=discoveryDock.querySelector('[data-discovery-inputs]'),groups=Object.entries(inputs);preview.innerHTML=`<strong>Recommendation inputs</strong>${groups.length?groups.map(([group,values])=>`<small>${group}: ${Object.values(values).flat().join(', ')}</small>`).join(''):'<small>Answers will form future recommendation inputs. No recommendations are made here.</small>'}`;}
discoveryStore.subscribe(renderDiscovery);store.subscribe(renderDiscovery);renderDiscovery();

const strategyDock=document.createElement('aside');strategyDock.className='strategy-dock';strategyDock.innerHTML='<header><div><small>Rally working record</small><strong>Strategy / Vision</strong></div><button data-close-strategy>×</button></header><div data-strategy-summary></div><button data-draft-strategy>Draft / Refresh from Discovery</button><section data-strategy-fields></section><section data-strategy-output></section>';document.body.append(strategyDock);strategyToggle.onclick=()=>{strategyStore.ensureCurrent();strategyDock.classList.toggle('open');};strategyDock.querySelector('[data-close-strategy]').onclick=()=>strategyDock.classList.remove('open');strategyDock.querySelector('[data-draft-strategy]').onclick=()=>strategyStore.draftFromDiscovery(strategyStore.getState().selectedId);
function renderStrategy(){const state=strategyStore.getState();if(!state.selectedId)return;const item=strategyStore.get(state.selectedId),summary=strategyDock.querySelector('[data-strategy-summary]');summary.innerHTML=`<strong>${item.progress.state.replaceAll('-',' ')}</strong><small>${item.progress.requiredComplete}/${item.progress.requiredTotal} required decisions${item.staleFields.length?` · ${item.staleFields.length} Discovery update${item.staleFields.length===1?'':'s'} available`:''}${item.contextAvailable?'':' · original Website unavailable'}</small>`;const shell=strategyDock.querySelector('[data-strategy-fields]');shell.replaceChildren();for(const section of [...new Set(strategyFields.map(field=>field.section))]){const group=document.createElement('div');group.className='strategy-section';group.innerHTML=`<h3>${section}</h3>`;for(const field of strategyFields.filter(value=>value.section===section)){const current=item.fields[field.key],label=document.createElement('label');label.innerHTML=`<span>${field.label}${field.required?' *':''}</span><small>${current.source==='discovery'?(item.staleFields.includes(field.key)?'From Discovery · update available':'From Discovery'):current.source==='human'?'Human edited':'Unresolved'}</small>`;const control=field.kind==='list'?document.createElement('input'):document.createElement('textarea');control.value=Array.isArray(current.value)?current.value.join(', '):current.value;control.placeholder=field.kind==='list'?'Comma-separated values':'';control.onchange=()=>strategyStore.edit(item.id,field.key,control.value,'rally-staff');label.append(control);group.append(label);}shell.append(group);}const output=strategyStore.getStrategyOutput(item.id),preview=strategyDock.querySelector('[data-strategy-output]');preview.innerHTML=`<strong>Strategy output</strong>${Object.keys(output).length?Object.entries(output).map(([group,values])=>`<small>${group}: ${typeof values==='object'?Object.values(values).flat().join(', '):values}</small>`).join(''):'<small>Complete Strategy decisions to prepare downstream inputs. No recommendations are made here.</small>'}`;}
strategyStore.subscribe(renderStrategy);store.subscribe(renderStrategy);renderStrategy();

const packet=document.createElement('div');packet.className='strategy-packet';packet.innerHTML='<header><div><small>Interactive Strategy Packet</small><strong data-packet-title></strong></div><button data-close-packet>Return to Studio</button></header><nav data-packet-steps></nav><div data-packet-summary></div><main data-packet-content></main><footer><button data-packet-previous>Previous</button><button data-packet-next>Next</button></footer>';document.body.append(packet);packetToggle.onclick=()=>{packetStore.open();packet.classList.add('open');};packet.querySelector('[data-close-packet]').onclick=()=>{packetStore.close();packet.classList.remove('open');};packet.querySelector('[data-packet-previous]').onclick=()=>packetStore.previous();packet.querySelector('[data-packet-next]').onclick=()=>packetStore.next();
function packetPreview(document,pageId){const page=document.pages[pageId],fragment=window.document.createElement('div');fragment.className='packet-preview-canvas';for(const [name,value] of Object.entries({'--primary':document.designSettings.primaryColor,'--secondary':document.designSettings.secondaryColor,'--radius':`${document.designSettings.radius}px`,'--space':`${document.designSettings.spacing}px`}))fragment.style.setProperty(name,value);fragment.style.fontFamily=document.designSettings.fontFamily;for(const id of page.componentInstanceIds){const instance=document.componentInstances[id];if(instance.hidden)continue;const node=registry.resolveVariant(instance.definitionType,instance.variantId).render(structuredClone(instance.content),document.designSettings);node.removeAttribute('contenteditable');fragment.append(node);}return fragment;}
function renderPacket(){const view=packetStore.getState();if(!view)return;const document=store.getState(),summary=packetStore.summary(),discovery=discoveryStore.get(view.discoveryResponseSetId),strategy=strategyStore.get(view.strategyId),steps=packet.querySelector('[data-packet-steps]');packet.querySelector('[data-packet-title]').textContent=document.website.name;steps.replaceChildren(...packetStore.steps.map((step,index)=>{const button=document.createElement('button');button.classList.toggle('active',step===view.currentStep);button.textContent=`${index+1}. ${step==='preview'?'Website Preview':step[0].toUpperCase()+step.slice(1)}`;button.onclick=()=>packetStore.setStep(step);return button;}));packet.querySelector('[data-packet-summary]').innerHTML=`<strong>${summary.ready?'Packet ready':'Working packet'}</strong><small>Discovery ${summary.discoveryState} · Strategy ${summary.strategyState} · ${summary.pageCount} page${summary.pageCount===1?'':'s'}</small>`;const content=packet.querySelector('[data-packet-content]');content.replaceChildren();if(view.currentStep==='discovery'){const values=discoveryStore.getRecommendationInputs(view.discoveryResponseSetId);content.innerHTML=`<section class="packet-copy"><h1>What we understand</h1>${Object.entries(values).map(([group,items])=>`<article><h2>${group.replaceAll('-',' ')}</h2><p>${Object.values(items).flat().join(', ')}</p></article>`).join('')||'<p>Discovery answers have not been provided yet.</p>'}<button data-open-discovery>Edit in Discovery</button></section>`;content.querySelector('button').onclick=()=>{discoveryDock.classList.add('open');packet.classList.remove('open');};}else if(view.currentStep==='strategy'){const shell=document.createElement('section');shell.className='packet-copy';shell.innerHTML=`<h1>Strategy / Vision</h1><p>${strategy.progress.requiredComplete}/${strategy.progress.requiredTotal} required decisions</p>`;for(const field of strategyFields){const label=document.createElement('label');label.innerHTML=`<span>${field.label}${field.required?' *':''}</span><small>${strategy.fields[field.key].source}</small>`;const control=document.createElement('textarea');control.value=Array.isArray(strategy.fields[field.key].value)?strategy.fields[field.key].value.join(', '):strategy.fields[field.key].value;control.onchange=()=>strategyStore.edit(strategy.id,field.key,control.value,'rally-staff');label.append(control);shell.append(label);}content.append(shell);}else{const controls=document.createElement('aside');controls.className='packet-design';if(view.currentStep==='design'){controls.innerHTML='<h1>Design Direction</h1>';for(const [key,label,type] of [['primaryColor','Primary color','color'],['secondaryColor','Secondary color','color'],['radius','Corner radius','range'],['spacing','Spacing','range']]){const row=document.createElement('label'),input=document.createElement('input');row.textContent=label;input.type=type;input.value=document.designSettings[key];if(type==='range'){input.min=key==='radius'?0:12;input.max=key==='radius'?36:48;}input.onchange=()=>store.updateDesignSettings({[key]:type==='range'?Number(input.value):input.value});row.append(input);controls.append(row);}const font=document.createElement('select');['Inter, ui-sans-serif, system-ui, sans-serif','Georgia, serif','system-ui, sans-serif'].forEach(value=>font.add(new Option(value.split(',')[0],value)));font.value=document.designSettings.fontFamily;font.onchange=()=>store.updateDesignSettings({fontFamily:font.value});const fontLabel=document.createElement('label');fontLabel.textContent='Typography';fontLabel.append(font);controls.append(fontLabel);}const preview=document.createElement('section');preview.className='packet-website';const pageNav=document.createElement('nav');for(const pageId of document.website.pageIds){const button=document.createElement('button');button.textContent=document.pages[pageId].name;button.classList.toggle('active',pageId===view.previewPageId);button.onclick=()=>packetStore.setPreviewPage(pageId);pageNav.append(button);}preview.append(pageNav,packetPreview(document,view.previewPageId));if(view.currentStep==='design')content.append(controls);content.append(preview);}const index=packetStore.steps.indexOf(view.currentStep);packet.querySelector('[data-packet-previous]').disabled=index===0;packet.querySelector('[data-packet-next]').disabled=index===packetStore.steps.length-1;}
packetStore.subscribe(renderPacket);store.subscribe(renderPacket);discoveryStore.subscribe(renderPacket);strategyStore.subscribe(renderPacket);

const commentsDock = document.createElement('aside'); commentsDock.className = 'comments-dock'; commentsDock.innerHTML = '<header><div><small>Review lens</small><strong>Conversations</strong></div><button data-close-comments>×</button></header><section data-review-sessions></section><div class="comment-filters"><select data-page-filter><option value="all">All pages</option><option value="current">Current page</option></select><select data-status-filter><option value="open">Open</option><option value="resolved">Resolved</option><option value="all">All statuses</option></select></div><button data-new-page-comment>＋ Page conversation</button><ol data-conversation-list></ol><section data-conversation-detail></section>'; document.body.append(commentsDock);
commentsToggle.onclick = () => { commentsOpen = !commentsOpen; commentsDock.classList.toggle('open', commentsOpen); render(store.getState()); }; commentsDock.querySelector('[data-close-comments]').onclick = () => { commentsOpen = false; commentsDock.classList.remove('open'); render(store.getState()); };
commentsDock.querySelector('[data-page-filter]').onchange = event => conversationStore.setFilters({ page: event.target.value }); commentsDock.querySelector('[data-status-filter]').onchange = event => conversationStore.setFilters({ status: event.target.value });

function openCommentDialog({ pageId, componentInstanceId = null }) { const overlay = document.createElement('div'); overlay.className = 'page-dialog comment-dialog'; overlay.innerHTML = `<form><h2>${componentInstanceId ? 'Component conversation' : 'Page conversation'}</h2><label>Message<textarea required></textarea></label><label>Actor<select><option value="local-user">Local user</option><option value="rally-staff">Rally staff</option><option value="client">Client</option></select></label><div><button type="button">Cancel</button><button type="submit">Start conversation</button></div></form>`; overlay.querySelector('[type="button"]').onclick = () => overlay.remove(); overlay.querySelector('form').onsubmit = event => { event.preventDefault(); conversationStore.create({ pageId, componentInstanceId, body: overlay.querySelector('textarea').value, author: overlay.querySelector('select').value }); overlay.remove(); }; document.body.append(overlay); overlay.querySelector('textarea').focus(); }
commentsDock.querySelector('[data-new-page-comment]').onclick = () => openCommentDialog({ pageId: store.getState().workspace.activePageId });
const componentComment = document.createElement('button'); componentComment.textContent = 'Comment'; componentComment.onclick = () => { const state = store.getState(); openCommentDialog({ pageId: state.workspace.activePageId, componentInstanceId: state.workspace.selectedComponentId }); }; $('#context-panel .instance-actions').prepend(componentComment);

function openTaskDialog(conversation) { const overlay = document.createElement('div'); overlay.className = 'page-dialog task-dialog'; overlay.innerHTML = `<form><h2>Create task</h2><label>Title<input required value="${conversation.messages[0].body.replaceAll('&','&amp;').replaceAll('"','&quot;')}"></label><label>Description<textarea></textarea></label><label>Assignee<select><option value="">Unassigned</option><option value="local-user">Local user</option><option value="rally-staff">Rally staff</option><option value="client">Client</option></select></label><div><button type="button">Cancel</button><button type="submit">Create task</button></div></form>`; overlay.querySelector('[type="button"]').onclick = () => overlay.remove(); overlay.querySelector('form').onsubmit = event => { event.preventDefault(); taskStore.createFromConversation(conversation.id, { title: overlay.querySelector('input').value, description: overlay.querySelector('textarea').value, assignedTo: overlay.querySelector('select').value || null }); overlay.remove(); tasksOpen = true; tasksDock.classList.add('open'); }; document.body.append(overlay); overlay.querySelector('input').select(); }

function renderConversations() { const list = commentsDock.querySelector('[data-conversation-list]'), items = conversationStore.list(), selectedId = conversationStore.getState().selectedId; list.replaceChildren(...items.map(item => { const row = document.createElement('li'), button = document.createElement('button'); row.classList.toggle('selected', item.id === selectedId); button.innerHTML = `<strong>${item.messages[0].body}</strong><small>${item.status} · ${item.anchorState.available ? (item.componentInstanceId ? 'Component' : 'Page') : 'Anchor unavailable'}</small>`; button.onclick = () => conversationStore.select(item.id); row.append(button); return row; })); const detail = commentsDock.querySelector('[data-conversation-detail]'); detail.replaceChildren(); if (!selectedId) return; const item = conversationStore.get(selectedId), heading = document.createElement('h3'); heading.textContent = item.anchorState.available ? 'Conversation' : 'Conversation · anchor unavailable'; const messages = document.createElement('ol'); messages.replaceChildren(...item.messages.map(message => { const row = document.createElement('li'); row.innerHTML = `<p>${message.body}</p><small>${message.author.name} · ${new Date(message.createdAt).toLocaleString()}</small>`; return row; })); const status = document.createElement('select'); conversationStore.statuses.forEach(value => { const option = new Option(value.replaceAll('-',' '), value); option.selected = value === item.status; status.add(option); }); status.onchange = () => conversationStore.setStatus(item.id, status.value); const taskButton = document.createElement('button'); taskButton.textContent = 'Create Task'; taskButton.onclick = () => openTaskDialog(item); const linked = document.createElement('div'); linked.className = 'linked-tasks'; linked.innerHTML = '<strong>Linked tasks</strong>'; for (const taskId of item.linkedTaskIds || []) { const task = taskStore.get(taskId), button = document.createElement('button'); button.textContent = `${task.title} · ${task.status}`; button.onclick = () => { taskStore.select(taskId); tasksOpen = true; tasksDock.classList.add('open'); }; linked.append(button); } const reply = document.createElement('form'); reply.innerHTML = '<textarea required placeholder="Reply"></textarea><select><option value="local-user">Local user</option><option value="rally-staff">Rally staff</option><option value="client">Client</option></select><button>Reply</button>'; reply.onsubmit = event => { event.preventDefault(); conversationStore.reply(item.id, reply.querySelector('textarea').value, reply.querySelector('select').value); }; detail.append(heading, status, messages, taskButton, linked, reply); }
conversationStore.subscribe(() => { renderConversations(); render(store.getState()); }); renderConversations();

const tasksDock = document.createElement('aside'); tasksDock.className = 'tasks-dock'; tasksDock.innerHTML = '<header><div><small>Current Website</small><strong>Tasks</strong></div><button data-close-tasks>×</button></header><select data-task-filter><option value="all">All statuses</option><option value="todo">To do</option><option value="in-progress">In progress</option><option value="blocked">Blocked</option><option value="done">Done</option></select><ol data-task-list></ol><section data-task-detail></section>'; document.body.append(tasksDock);
