  const heading = document.createElement('div'); heading.className = 'review-heading'; heading.innerHTML = '<strong>Review Sessions</strong><button>＋ New</button>'; heading.querySelector('button').onclick = () => reviewSessionStore.create(`Website review ${sessions.length + 1}`);
  const general = document.createElement('button'); general.className = 'general-conversations'; general.textContent = 'General Website conversations'; general.onclick = () => { conversationStore.setActiveReviewSession(null); conversationStore.setFilters({ session: 'all' }); };
  const list = document.createElement('div'); list.className = 'review-session-list'; list.replaceChildren(...sessions.map(item => { const button = document.createElement('button'); button.classList.toggle('selected', item.id === state.selectedId); button.innerHTML = `<strong>${item.title}</strong><small>${item.status}</small>`; button.onclick = () => { reviewSessionStore.select(item.id); conversationStore.setFilters({ session: item.id }); }; return button; })); shell.append(heading, general, list);
  if (!state.selectedId || !state.sessions[state.selectedId] || state.sessions[state.selectedId].websiteId !== store.getState().website.id) return;
  const item = reviewSessionStore.get(state.selectedId), summary = document.createElement('div'); summary.className = 'review-summary'; summary.innerHTML = `<b>${item.summary.ready ? 'Conversations ready' : `${item.summary.unresolved} unresolved`}</b><small>Open ${item.summary.counts.open} · Rally ${item.summary.counts['waiting-on-rally']} · Client ${item.summary.counts['waiting-on-client']} · Resolved ${item.summary.counts.resolved}</small><small>Guided review: ${item.questionnaireSummary.requiredAnswered}/${item.questionnaireSummary.requiredTotal} required · ${item.questionnaireSummary.state}</small>${item.checkpoint ? `<small>Checkpoint ${new Date(item.checkpoint.capturedAt).toLocaleString()}</small>` : ''}`;
  const guided = document.createElement('div'); guided.className = 'guided-review'; guided.innerHTML = '<strong>Guided review</strong>';
  if (!item.checkpoint) guided.insertAdjacentHTML('beforeend','<small>Start the review to answer checkpoint questions.</small>');
  else for (const question of item.questions) { const response = item.responses[question.id], field = document.createElement('label'); field.innerHTML = `<span>${question.label}${question.required ? ' *' : ''}</span><small>${question.helperText}</small>`; let control; if (question.type === 'free-text') { control = document.createElement('textarea'); control.value = response?.answer || ''; } else { control = document.createElement('select'); control.append(new Option('Choose…',''), ...question.choices.map(value => new Option(value.replaceAll('-',' '), value))); control.value = response?.answer || ''; } control.disabled = item.status === 'completed'; control.onchange = () => reviewSessionStore.respond(item.id, question.id, control.value, 'client'); field.append(control); guided.append(field); }
  const actions = document.createElement('div'); actions.className = 'review-actions'; if (item.status === 'draft') { const start = document.createElement('button'); start.textContent = 'Start review'; start.onclick = () => reviewSessionStore.start(item.id); actions.append(start); } if (item.status === 'active') { const complete = document.createElement('button'); complete.textContent = 'Complete'; complete.onclick = () => reviewSessionStore.complete(item.id); actions.append(complete); } const override = document.createElement('input'); override.placeholder = 'Override reason for approval blockers'; const approve = document.createElement('button'); approve.textContent = item.currentApproval ? 'Approved' : 'Approve'; approve.disabled = !!item.currentApproval || !item.checkpoint; approve.onclick = () => { try { reviewSessionStore.approve(item.id, { overrideReason: override.value }); } catch (error) { override.setCustomValidity(error.message); override.reportValidity(); } }; actions.append(override, approve); if (item.currentApproval) { const revoke = document.createElement('button'); revoke.textContent = 'Revoke'; revoke.onclick = () => reviewSessionStore.revoke(item.id); actions.append(revoke); }
